questions.starter:
#include <stdio.h>

int main() {
    int sum = 0;
    // write your for loop here

    printf("Sum of even numbers: %d\n", sum);
    return 0;
}

questions.solution:
#include <stdio.h>

int main() {
    int sum = 0;
    for (int i = 2; i <= 20; i += 2) {
        sum += i;
    }
    printf("Sum of even numbers: %d\n", sum);
    return 0;
}
